--
-- Table structure for table `jadwal_ujians`
--

DROP TABLE IF EXISTS `jadwal_ujians`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `jadwal_ujians` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `ujian_id` bigint unsigned NOT NULL,
  `mata_pelajaran_id` bigint unsigned DEFAULT NULL,
  `nama_mata_pelajaran_custom` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `tanggal_ujian` date NOT NULL,
  `waktu_mulai` time NOT NULL,
  `waktu_selesai` time NOT NULL,
  `level_id` bigint unsigned DEFAULT NULL,
  `ustadz_id` bigint unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `jadwal_ujians_ujian_id_foreign` (`ujian_id`),
  KEY `jadwal_ujians_mata_pelajaran_id_foreign` (`mata_pelajaran_id`),
  KEY `jadwal_ujians_level_id_foreign` (`level_id`),
  KEY `jadwal_ujians_ustadz_id_foreign` (`ustadz_id`),
  CONSTRAINT `jadwal_ujians_level_id_foreign` FOREIGN KEY (`level_id`) REFERENCES `levels` (`id`) ON DELETE SET NULL,
  CONSTRAINT `jadwal_ujians_mata_pelajaran_id_foreign` FOREIGN KEY (`mata_pelajaran_id`) REFERENCES `mata_pelajarans` (`id`) ON DELETE SET NULL,
  CONSTRAINT `jadwal_ujians_ujian_id_foreign` FOREIGN KEY (`ujian_id`) REFERENCES `ujians` (`id`) ON DELETE CASCADE,
  CONSTRAINT `jadwal_ujians_ustadz_id_foreign` FOREIGN KEY (`ustadz_id`) REFERENCES `ustadzs` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=145 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

