--
-- Table structure for table `murids`
--

DROP TABLE IF EXISTS `murids`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `murids` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `wali_murid_id` bigint unsigned DEFAULT NULL,
  `nism` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `nisn` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `nik` text COLLATE utf8mb4_unicode_ci,
  `nik_hash` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `nama_lengkap` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `nama_panggilan` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `jenis_kelamin` enum('L','P') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `tempat_lahir` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `tanggal_lahir` date DEFAULT NULL,
  `anak_ke` int DEFAULT NULL,
  `hub_kel` enum('Anak Kandung','Anak Tiri','Anak Angkat','Cucu','Lainnya') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Anak Kandung',
  `nik_ayah` text COLLATE utf8mb4_unicode_ci,
  `nama_ayah` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `status_ayah` enum('Hidup','Meninggal') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Hidup',
  `nik_ibu` text COLLATE utf8mb4_unicode_ci,
  `nama_ibu` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `status_ibu` enum('Hidup','Meninggal') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Hidup',
  `foto` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `status` enum('Aktif','Lulus','Pindah','Berhenti','Meninggal') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Aktif',
  `tahun_masuk` bigint unsigned DEFAULT NULL,
  `level_masuk` bigint unsigned DEFAULT NULL,
  `ruangan_masuk` bigint unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `murids_nism_unique` (`nism`),
  UNIQUE KEY `murids_nisn_unique` (`nisn`),
  UNIQUE KEY `murids_nik_hash_unique` (`nik_hash`),
  KEY `murids_wali_murid_id_foreign` (`wali_murid_id`),
  KEY `murids_tahun_masuk_foreign` (`tahun_masuk`),
  KEY `murids_level_masuk_foreign` (`level_masuk`),
  KEY `murids_ruangan_masuk_foreign` (`ruangan_masuk`),
  CONSTRAINT `murids_level_masuk_foreign` FOREIGN KEY (`level_masuk`) REFERENCES `levels` (`id`) ON DELETE SET NULL,
  CONSTRAINT `murids_ruangan_masuk_foreign` FOREIGN KEY (`ruangan_masuk`) REFERENCES `ruangans` (`id`) ON DELETE SET NULL,
  CONSTRAINT `murids_tahun_masuk_foreign` FOREIGN KEY (`tahun_masuk`) REFERENCES `tahun_pelajarans` (`id`) ON DELETE SET NULL,
  CONSTRAINT `murids_wali_murid_id_foreign` FOREIGN KEY (`wali_murid_id`) REFERENCES `wali_murids` (`id`) ON DELETE RESTRICT
) ENGINE=InnoDB AUTO_INCREMENT=518 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

