DROP TABLE IF EXISTS `pembelian_detail_koperasis`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `pembelian_detail_koperasis` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `pembelian_id` bigint unsigned NOT NULL,
  `produk_id` bigint unsigned NOT NULL,
  `kode_produk` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `nama_produk` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `satuan` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pcs',
  `jumlah` int NOT NULL DEFAULT '1',
  `harga_beli_satuan` decimal(12,2) NOT NULL DEFAULT '0.00',
  `harga_jual_satuan` decimal(12,2) NOT NULL DEFAULT '0.00',
  `subtotal` decimal(14,2) NOT NULL DEFAULT '0.00',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `pembelian_detail_koperasis_pembelian_id_foreign` (`pembelian_id`),
  KEY `pembelian_detail_koperasis_produk_id_foreign` (`produk_id`),
  CONSTRAINT `pembelian_detail_koperasis_pembelian_id_foreign` FOREIGN KEY (`pembelian_id`) REFERENCES `pembelian_koperasis` (`id`) ON DELETE CASCADE,
  CONSTRAINT `pembelian_detail_koperasis_produk_id_foreign` FOREIGN KEY (`produk_id`) REFERENCES `produk_koperasis` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
