DROP TABLE IF EXISTS `pembelian_koperasis`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `pembelian_koperasis` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `nomor_faktur` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `nomor_faktur_supplier` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `supplier` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `tanggal` datetime NOT NULL,
  `petugas_id` bigint unsigned NOT NULL,
  `total_item` int NOT NULL DEFAULT '0',
  `total_nominal` decimal(14,2) NOT NULL DEFAULT '0.00',
  `ongkir` decimal(14,2) NOT NULL DEFAULT '0.00',
  `diskon` decimal(14,2) NOT NULL DEFAULT '0.00',
  `metode_pembayaran` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Tunai_Kas',
  `nominal_bayar` decimal(14,2) NOT NULL DEFAULT '0.00',
  `kembalian` decimal(14,2) NOT NULL DEFAULT '0.00',
