INSERT INTO `pengumumans` VALUES (1,'Musyawarah Akhir Tahun Pelajaran 1447-1448 H','<p>Assalamualaikum War. Wab.</p><p>Sehubungan dengan persiapan pelaksanaan kegiatan rutin Akhir Tahun Pelajaran, kami kepengurusan Madrasah mengundang Ustadz/Ustadzah nanti</p><p>Hari : Rabu malam Kamis,</p><p>Tanggal : 18 Rabiul Tsani 1448 H / 30 September 2026</p><p>Tempat : Musholla Hidayatus Shibyan</p><p>Agenda : Persiapan IMNI, dan Haflatul Ikhtibar 52</p><p><br></p><p>oleh karenanya apabila tidak ada udzur atau halangan kami mengharap kehadirannya.</p><p>Demikian dari kami, atas perhatiaannya disampaikan terima kasih dan mohon dimaklumi adanya</p><p><br></p><p>Hormat kami,</p><p>Kepala Administrator</p><p><br></p>',NULL,'Penting','Ustadz','Draft','2026-09-17','2026-09-30',1,'2026-09-17 02:43:23','2026-09-17 15:26:24');
/*!40000 ALTER TABLE `pengumumans` ENABLE KEYS */;
UNLOCK TABLES;

