DROP TABLE IF EXISTS `wali_murids`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `wali_murids` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `no_registrasi` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `no_kk` text COLLATE utf8mb4_unicode_ci,
  `no_kk_hash` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `kepala_keluarga` enum('Ayah','Ibu','Wali') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Ayah',
  `nama_kepala_keluarga` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `no_hp` varchar(15) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `pin` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `is_pin_changed` tinyint(1) NOT NULL DEFAULT '0',
  `alamat_detail` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `kampung_id` bigint unsigned NOT NULL,
  `is_ustadz` tinyint(1) NOT NULL DEFAULT '0',
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `wali_murids_no_registrasi_unique` (`no_registrasi`),
  UNIQUE KEY `wali_murids_no_kk_hash_unique` (`no_kk_hash`),
  KEY `wali_murids_kampung_id_foreign` (`kampung_id`),
  CONSTRAINT `wali_murids_kampung_id_foreign` FOREIGN KEY (`kampung_id`) REFERENCES `kampungs` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=370 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
